import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        freq = {}
        duplicates = 0

        for x in A:
            if x in freq:
                freq[x] += 1
            else:
                freq[x] = 1

        for count in freq.values():
            if count > 1:
                duplicates += count - 1

        results.append(str(duplicates))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
